export interface Teacher {
  id: string;
  firstName: string;
  lastName: string;
  role: string;
  bio: string;
  photoUrl: string;
}

export interface PieceInfo {
  id: string;
  name: string;
  type: 'p' | 'n' | 'b' | 'r' | 'q' | 'k';
  value: string;
  summary: string;
  description: string;
  demoPosition: {
    pieceSquare: string;
    validMoves: string[];
  };
}

export interface SocialLink {
  platform: string;
  name: string;
  url: string;
  icon: string;
}

export interface UserProfile {
  id: string;
  full_name: string;
  role: 'user' | 'admin';
  created_at: string;
  email?: string;
  phone?: string;
}

export interface ContactRequest {
  id: string;
  value: string;
  type: 'email' | 'phone';
  status: 'new' | 'contacted';
  created_at: string;
}

export type BookLevel = 'beginner' | 'intermediate' | 'advanced';

export interface Book {
  id: string;
  title: string;
  author: string;
  description: string;
  level: BookLevel;
  cover_url: string | null;
  file_url: string;
  file_name: string;
  created_at: string;
}

